flow.typescript:
// D15 · Part 0~9 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_flow.ts   (모의 받아쓰기 결과 · 인터넷·GPU·API 키·Whisper 불필요)
//   목표 정하기 → 문장 틀 나누기와 누수 검사 → 기준선 → (LoRA 학습 결과) → 용어 사전 후처리 → 목표 판정 → 부트스트랩 → 리포트 한 줄 순서를 작게 한 번에 돈다
//   흉내 낸 부분: 실제 Whisper · LoRA 학습 대신 용어 글자를 일정 확률로 틀리게 만든 받아쓰기 결과(원래 50% → LoRA 15%), 학습은 하지 않음
const TERMS = ["심방세동", "트로포닌", "와파린", "크레아티닌", "패혈증", "대상포진", "항응고제", "당화혈색소"];
const TEMPLATES = ["오늘 회의에서 {t} 문제를 다시 다뤘습니다", "{t} 관련 자료를 정리해 주세요", "보고서에 {t} 항목을 추가했습니다",
  "기록지에 {t} 항목을 표시해 주세요", "{t} 경과를 내일 다시 보겠습니다", "고객에게 {t} 설명을 드렸습니다"];
const N_TRAIN_TPL = 3;
const GOALS: [string, string, number][] = [["용어(%)", ">=", 70.0], ["CER 변화(%p)", "<=", 1.0]];
const FILL = [..."가나다라마바사아자차"];
type Row = { text: string; term: string };

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0);
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
const normalize = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, "");

function editDistance(a: string, b: string): number {
  const d = Array.from({ length: b.length + 1 }, (_, j) => j);
  for (let i = 1; i <= a.length; i++) {
    let prev = d[0];
    d[0] = i;
    for (let j = 1; j <= b.length; j++) {
      const tmp = d[j];
      d[j] = Math.min(d[j] + 1, d[j - 1] + 1, prev + (a[i - 1] === b[j - 1] ? 0 : 1));
      prev = tmp;
    }
  }
  return d[b.length];
}

function similarity(a: string, b: string): number {
  // 비슷한 정도 = 2 × 겹치는 글자 ÷ 전체 글자 수 (difflib.SequenceMatcher.ratio 와 같은 계산)
  const matched = (alo: number, ahi: number, blo: number, bhi: number): number => {
    let bi = 0, bj = 0, bk = 0;
    for (let i = alo; i < ahi; i++) {
      for (let j = blo; j < bhi; j++) {
        let k = 0;
        while (i + k < ahi && j + k < bhi && a[i + k] === b[j + k]) k++;
        if (k > bk) { bi = i; bj = j; bk = k; }
      }
    }
    return bk === 0 ? 0 : bk + matched(alo, bi, blo, bj) + matched(bi + bk, ahi, bj + bk, bhi);
  };
  return a.length + b.length === 0 ? 1 : (2 * matched(0, a.length, 0, b.length)) / (a.length + b.length);
}

// 1) 데이터 설계: 틀 단위로 나누고 누수 검사
const trainTexts = TEMPLATES.slice(0, N_TRAIN_TPL).flatMap((t) => TERMS.map((w) => t.replace("{t}", w)));
const base: Row[] = TEMPLATES.slice(N_TRAIN_TPL).flatMap((t) => TERMS.map((w) => ({ text: t.replace("{t}", w), term: w })));
const test: Row[] = [...base, ...base]; // 시험 48문장(합성음 두 목소리 가정)
const testSet = new Set(test.map((r) => normalize(r.text)));
const leak = trainTexts.filter((s) => testSet.has(normalize(s))).length;
console.log(`학습 ${trainTexts.length}문장 · 시험 ${test.length}문장 · 누수 ${leak}개`);

// 2) 받아쓰기 결과(모의): 용어 글자를 rate 확률로 틀림
function corrupt(row: Row, rate: number): string {
  const a = row.text.indexOf(row.term);
  return [...row.text].map((c, i) => (i >= a && i < a + row.term.length && rnd() < rate ? FILL[Math.floor(rnd() * FILL.length)] : c)).join("");
}

// 3) 용어 사전 후처리
function fixTerms(text: string, cutoff: number = 0.75): string {
  return text.split(/\s+/).map((word) => {
    let cand = TERMS[0], score = -1;
    for (const t of TERMS) {
      const s = similarity(word.slice(0, t.length), t);
      if (s > score) { cand = t; score = s; }
    }
    return cutoff <= score && score < 1 ? cand + word.slice(cand.length) : word;
  }).join(" ");
}

const PRED: Record<string, string[]> = { "① 원래": test.map((r) => corrupt(r, 0.5)) };
PRED["③ LoRA"] = test.map((r) => corrupt(r, 0.15));
PRED["⑤ LoRA + 용어 사전"] = PRED["③ LoRA"].map((p) => fixTerms(p));
const perCer: Record<string, number[]> = {}, term: Record<string, number> = {};
for (const [n, ps] of Object.entries(PRED)) {
  perCer[n] = ps.map((p, i) => (100 * editDistance(normalize(test[i].text), normalize(p))) / normalize(test[i].text).length);
  term[n] = (100 * ps.filter((p, i) => normalize(p).includes(normalize(test[i].term))).length) / ps.length;
}
const generalChange: Record<string, number> = { "① 원래": 0.0, "③ LoRA": 0.4, "⑤ LoRA + 용어 사전": 0.5 }; // 일반 문장 CER 변화(%p): 학습 때 replay로 지킨 값(예시)
for (const n of Object.keys(PRED)) console.log(`${n.padEnd(20)} 용어 ${term[n].toFixed(1).padStart(5)}% · 도메인 CER ${mean(perCer[n]).toFixed(2).padStart(5)}% · 일반 변화 ${generalChange[n] >= 0 ? "+" : ""}${generalChange[n].toFixed(1)}%p`);

// 4) 목표 판정과 부트스트랩
const FINAL = "⑤ LoRA + 용어 사전";
const vals: Record<string, number> = { "용어(%)": term[FINAL], "CER 변화(%p)": generalChange[FINAL] };
const ok = GOALS.map(([k, op, t]) => (op === ">=" ? vals[k] >= t : vals[k] <= t));
const g = mulberry32(0);
const diffs: number[] = [];
for (let k = 0; k < 2000; k++) {
  const idx = Array.from({ length: test.length }, () => Math.floor(g() * test.length));
  diffs.push(mean(idx.map((i) => perCer["① 원래"][i])) - mean(idx.map((i) => perCer[FINAL][i])));
}
diffs.sort((a, b) => a - b);
const q = (p: number): number => {
  const pos = ((diffs.length - 1) * p) / 100;
  const lo = Math.floor(pos);
  return diffs[lo] + (diffs[Math.min(lo + 1, diffs.length - 1)] - diffs[lo]) * (pos - lo);
};
const [lo, hi] = [q(2.5), q(97.5)];
const verdict = lo > 0 ? "개선 ✓" : hi < 0 ? "악화 ✗" : "차이 불확실";
console.log(`목표 ${ok.filter(Boolean).length}/${GOALS.length} 달성 · CER 개선 95% [${lo.toFixed(2)}, ${hi.toFixed(2)}] → ${verdict}`);
console.log(`리포트 한 줄: 용어 정확도 ${term["① 원래"].toFixed(0)}% → ${term[FINAL].toFixed(0)}% (${verdict})`);
check(leak === 0 && verdict === "개선 ✓" && term[FINAL] > term["① 원래"] + 30 && ok.every(Boolean),
  "누수 0개 · 용어 정확도 크게 향상 · 목표 모두 달성 · 부트스트랩 개선 ✓ 이어야 해요.");

goals.typescript:
// D15 · Part 1 · 요구 사항 → 지표 (프로젝트 카드와 목표표) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_goals.ts   (측정값은 코드 안의 예시 · 인터넷 불필요)
//   '외래 진료 기록' 프로젝트의 요구를 지표 · 방향(≥ · ≤) · 목표값으로 바꾸고, 측정값과 비교해 ✅ · ❌ 를 판정한다. 방향을 거꾸로 쓰면 판정이 뒤집히는 것도 확인한다
//   흉내 낸 부분: 실제 학습 결과 대신 예시 측정값(원래 모델 vs 우리 모델)
const PROJECT = {
  team: "1조", domain: "의료", slug: "team1-medical",
  scenario: "외래 진료 중 의사가 말한 내용을 진료 기록 초안으로 받아쓴다",
  privacy: "환자 음성은 외부 API로 보낼 수 없음 → 병원 안 GPU에서 도는 로컬 모델",
};
type Goal = [metric: string, op: ">=" | "<=", target: number, why: string];
const GOALS: Goal[] = [
  ["용어(%) · 도메인 TTS", ">=", 90.0, "핵심 용어를 틀리면 기록을 다시 써야 한다"],
  ["용어(%) · 내 목소리 도메인", ">=", 70.0, "합성음이 아닌 사람 목소리에서도 쓸 만해야 한다"],
  ["CER 변화(%p) · 일반 Zeroth", "<=", 1.0, "일상 문장 실력이 1%p 넘게 나빠지면 안 된다"],
  ["RTF", "<=", 0.2, "5분 진료 녹음을 1분 안에 받아쓴다"],
];
const MEASURED: Record<string, number> = { // 우리 모델의 측정값 (원래 모델의 일반 CER 7.0%, 학습 후 7.6% → 변화 +0.6%p)
  "용어(%) · 도메인 TTS": 93.0, "용어(%) · 내 목소리 도메인": 62.0, "CER 변화(%p) · 일반 Zeroth": 7.6 - 7.0, RTF: 0.15,
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const meets = (v: number, op: string, target: number): boolean => (op === ">=" ? v >= target : v <= target);

if (!/^[A-Za-z0-9-]+$/.test(PROJECT.slug)) throw new Error("slug는 영문 · 숫자 · 하이픈만");
console.log(`${PROJECT.team} · ${PROJECT.domain} · ${PROJECT.scenario}\n개인정보 조건: ${PROJECT.privacy}`);
console.log("지표".padEnd(28) + "목표".padStart(9) + "측정".padStart(8) + "  판정 · 이유");
const verdicts: boolean[] = [];
for (const [key, op, target, why] of GOALS) {
  const v = MEASURED[key];
  const ok = meets(v, op, target);
  verdicts.push(ok);
  console.log(key.padEnd(28) + `${op === ">=" ? "≥" : "≤"} ${target}`.padStart(9) + v.toFixed(2).padStart(8) + `  ${ok ? "✅ 달성" : "❌ 미달"} · ${why}`);
}
console.log(`목표 ${verdicts.filter(Boolean).length}/${GOALS.length} 달성`);
const wrong = meets(MEASURED.RTF, ">=", 0.2); // RTF에 방향을 거꾸로 쓰면
console.log("RTF 방향을 거꾸로(≥ 0.2) 쓰면 판정:", wrong ? "달성(틀린 판정!)" : "미달");
check(meets(91, ">=", 90) && meets(0.4, "<=", 1.0) && !meets(1.5, "<=", 1.0) && meets(1.0, "<=", 1.0) && verdicts.join() === "true,false,true,true" && !wrong,
  "'이상(≥)' 지표는 클수록, '이하(≤)' 지표는 작을수록 좋아요. 내 목소리 용어(62%)만 미달이어야 해요.");

data.typescript:
// D15 · Part 2 · 데이터 설계: 용어 × 문장 틀과 누수 검사 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_data.ts   (소리 합성(TTS)은 하지 않고 문장 설계만 · 인터넷 불필요)
//   용어 12개 × 문장 틀 10개를 학습용 7개 · 시험용 3개로 나누고, 겹치는 문장(누수)이 없는지 검사한다. 일부러 틀 하나를 섞어 누수가 잡히는지도 확인한다
//   흉내 낸 부분: 증강(말 빠르기 변형)은 문장 수만 센다(실제로는 소리를 0.9 · 1.1배 속도로 바꿔 3배로 늘림)
const TERMS = ["심방세동", "트로포닌", "와파린", "메트포르민", "크레아티닌", "당화혈색소", "심근경색", "폐색전증", "패혈증", "대상포진", "항응고제", "인슐린 글라진"];
const TEMPLATES = [
  "오늘 회의에서 {t} 문제를 다시 다뤘습니다", "{t} 관련 자료를 정리해 주세요", "방금 말씀하신 {t} 부분을 다시 확인하겠습니다",
  "보고서에 {t} 항목을 추가했습니다", "{t} 때문에 일정이 조금 늦어졌습니다", "담당자에게 {t} 내용을 전달했습니다", "다음 주까지 {t} 검토를 마치겠습니다",
  "기록지에 {t} 항목을 표시해 주세요", "{t} 경과를 내일 다시 보겠습니다", "고객에게 {t} 설명을 드렸습니다",
];
const N_TRAIN_TPL = 7;
const SPEEDS = [0.9, 1.0, 1.1];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const normalize = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, "");

function leakCount(trainTexts: string[], testTexts: string[]): number {
  const test = new Set(testTexts.map(normalize));
  return new Set(trainTexts.map(normalize).filter((s) => test.has(s))).size;
}

const trainTpl = TEMPLATES.slice(0, N_TRAIN_TPL);
const testTpl = TEMPLATES.slice(N_TRAIN_TPL);
const trainTexts = trainTpl.flatMap((t) => TERMS.map((w) => t.replace("{t}", w)));
const testTexts = testTpl.flatMap((t) => TERMS.map((w) => t.replace("{t}", w)));
const leak = leakCount(trainTexts, testTexts);
const nAug = trainTexts.length * SPEEDS.length;
console.log(`학습 문장 ${trainTexts.length}개 → 증강 후 ${nAug}개 · 시험 문장 ${testTexts.length}개 · 겹치는 문장 ${leak}개`);
console.log("시험 문장 예:", testTexts.slice(0, 2));

const badTrain = [...trainTexts, TEMPLATES[8].replace("{t}", TERMS[0])]; // 시험 틀의 문장이 학습에 새어 들어간 경우
console.log("일부러 섞은 경우 겹치는 문장:", leakCount(badTrain, testTexts));
check(testTpl.every((t) => !trainTpl.includes(t)) && leak === 0 && testTexts.length === testTpl.length * TERMS.length && leakCount(badTrain, testTexts) === 1 && nAug === 252,
  "시험 틀은 학습 틀과 겹치면 안 되고(TEMPLATES[N_TRAIN_TPL:]), 새어 들어간 문장은 누수 검사가 잡아야 해요.");

record.typescript:
// D15 · Part 3 · 녹음 품질 점검과 16 kHz 모노 변환 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_record.ts   (합성 소리 · 마이크·ffmpeg·인터넷 불필요)
//   44.1 kHz 스테레오 소리를 16 kHz 모노로 바꾸고, 길이 · 최대 크기(클리핑) · 평균 크기로 '너무 짧음 · 클리핑 · 너무 작음'을 찾아낸다
//   흉내 낸 부분: 진짜는 ffmpeg(-ac 1 -ar 16000)로 변환하지만 여기서는 두 채널 평균 + 선형 보간으로 줄임(품질은 낮지만 길이 · 형식은 같음)
const SR = 16000;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function to16kMono(channels: Float64Array[], sr: number): Float32Array {
  const n0 = channels[0].length;
  const mono = Float64Array.from({ length: n0 }, (_, i) => channels.reduce((s, c) => s + c[i], 0) / channels.length); // 스테레오 → 모노
  const n = Math.round((n0 * SR) / sr);
  return Float32Array.from({ length: n }, (_, k) => {
    const pos = (k * (n0 - 1)) / (n - 1); // 선형 보간
    const i = Math.floor(pos);
    return mono[i] + (mono[Math.min(i + 1, n0 - 1)] - mono[i]) * (pos - i);
  });
}

function quality(y: Float32Array): { 초: number; 최대: number; 평균dB: number; 문제: string } {
  const peak = y.reduce((m, v) => Math.max(m, Math.abs(v)), 0);
  const rmsDb = 20 * Math.log10(Math.sqrt(y.reduce((s, v) => s + v * v, 0) / y.length) + 1e-9);
  const issues = ([[y.length / SR < 0.8, "너무 짧음"], [peak > 0.99, "클리핑"], [rmsDb < -40, "너무 작음"]] as [boolean, string][]).filter(([c]) => c).map(([, m]) => m);
  return { 초: Math.round((y.length / SR) * 10) / 10, 최대: Math.round(peak * 100) / 100, 평균dB: Math.round(rmsDb * 10) / 10, 문제: issues.join(", ") || "OK" };
}

const n44 = Math.floor(44100 * 1.5);
const left = Float64Array.from({ length: n44 }, (_, i) => 0.3 * Math.sin((2 * Math.PI * 220 * i) / 44100));
const right = Float64Array.from({ length: n44 }, (_, i) => 0.3 * Math.sin((2 * Math.PI * 330 * i) / 44100));
