const samples: [string, Float32Array][] = [["정상", tone(2, 0.3)], ["너무 짧음", tone(0.5, 0.3)], ["클리핑", tone(2, 3.0, true)], ["너무 작음", tone(2, 0.003)]]; // 클리핑: 입력이 너무 커서 윗부분이 잘림
