curves.typescript:
// D15 · Part 5 · 학습 곡선 진단 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_curves.ts   (수식으로 만든 학습 기록 · 인터넷·GPU 불필요)
//   LoRA 학습 기록(train · valid loss)이 '잘 배움 · 안 배움 · 외움(과적합) · 불안정' 중 무엇인지 규칙으로 진단하고, 가장 좋은 step(best)을 고른다
//   흉내 낸 부분: 실제 학습 대신 수식 + 잡음으로 만든 곡선 4개(loss는 step 12개, 6 step마다 기록하는 것과 같은 모양)
const STEPS = Array.from({ length: 12 }, (_, i) => 6 * (i + 1)); // 6, 12, ..., 72

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0);
const gauss = (s: number): number => s * Math.sqrt(-2 * Math.log(Math.max(rnd(), 1e-12))) * Math.cos(2 * Math.PI * rnd());
const noisy = (f: (s: number) => number, sd: number = 0.02): number[] => STEPS.map((_, s) => f(s) + gauss(sd));

const curves: Record<string, [number[], number[]]> = {
  "잘 배움": [noisy((s) => 2.0 * Math.exp(-s / 4) + 0.2), noisy((s) => 2.1 * Math.exp(-s / 4) + 0.3)],
  "안 배움": [noisy((s) => 2.0 - 0.01 * s), noisy((s) => 2.1 - 0.01 * s)],
  "외움": [noisy((s) => 2.0 * Math.exp(-s / 2) + 0.01), noisy((s) => 1.2 + 0.08 * s - 0.9 * Math.exp(-s / 1.5))],
  "불안정": [noisy((s) => 1.5 + 0.9 * (s % 3), 0.1), noisy((s) => 1.8 + 0.8 * (s % 4), 0.1)],
};

function diagnose(train: number[], valid: number[]): [string, number] {
  // 규칙: ① 오르내림이 크면 불안정 ② train이 거의 안 줄면 안 배움 ③ valid가 바닥 뒤 다시 오르면 외움 ④ 그 밖에는 잘 배움. best = valid가 가장 낮은 기록 번호
  const best = valid.indexOf(Math.min(...valid));
  const jitter = train.slice(1).reduce((s, v, i) => s + Math.abs(v - train[i]), 0) / (train.length - 1);
  const last = train.length - 1;
  if (jitter > 0.3) return ["불안정", best];
  if (train[last] > 0.85 * train[0]) return ["안 배움", best];
  if (valid[last] > valid[best] * 1.2 && train[last] < 0.5 * valid[last]) return ["외움", best];
  return ["잘 배움", best];
}

const result: Record<string, [string, number]> = {};
for (const [name, [tr, va]] of Object.entries(curves)) {
  const [verdict, best] = diagnose(tr, va);
  result[name] = [verdict, best];
  console.log(`${name.padEnd(6)} train ${tr[0].toFixed(2)}→${tr.at(-1)!.toFixed(2)} · valid 최저 ${va[best].toFixed(2)}(step ${STEPS[best]}) → 끝 ${va.at(-1)!.toFixed(2)} · 진단: ${verdict}`);
}
console.log("'외움'이면 마지막이 아니라 valid가 가장 낮았던 step의 모델(load_best_model_at_end)을 써야 해요:", STEPS[result["외움"][1]], "step");
check(Object.entries(result).every(([k, v]) => v[0] === k) && result["외움"][1] < STEPS.length - 1, "곡선 모양대로 진단이 나오고, 외움이면 best step이 마지막이 아니어야 해요.");

ci.typescript:
// D15 · Part 6 · 목표 · 신뢰구간 (최종 시스템 고르기) — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_ci.ts   (합성 문장별 점수 · 인터넷·GPU 불필요)
//   후보 3개를 목표표로 채점해 '달성한 목표 수 → 용어 정확도' 순으로 최종 시스템을 고르고, 부트스트랩 신뢰구간으로 개선이 우연이 아닌지 판정한다
//   흉내 낸 부분: 후보별 측정값과 문장별 CER은 예시 · 난수로 만든 값
const GOALS: [string, string, number][] = [["용어(%)", ">=", 90.0], ["CER 변화(%p)", "<=", 1.0], ["RTF", "<=", 0.2]];
const BOARD: Record<string, Record<string, number>> = { // 후보별 측정값
  "③ LoRA": { "용어(%)": 88.0, "CER 변화(%p)": 0.4, RTF: 0.15 },
  "④ LoRA + 프롬프트": { "용어(%)": 93.0, "CER 변화(%p)": 1.8, RTF: 0.17 },
  "⑤ LoRA + 용어 사전": { "용어(%)": 95.0, "CER 변화(%p)": 0.5, RTF: 0.15 },
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function mulberry32(seed: number): () => number {
  // 씨앗을 주면 늘 같은 순서의 난수를 주는 작은 생성기
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
const rnd = mulberry32(0);
const gauss = (m: number, s: number): number => m + s * Math.sqrt(-2 * Math.log(Math.max(rnd(), 1e-12))) * Math.cos(2 * Math.PI * rnd());
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;

const meets = (v: number, op: string, target: number): boolean => (op === ">=" ? v >= target : v <= target);
const nOk = (name: string): number => GOALS.filter(([k, op, t]) => meets(BOARD[name][k], op, t)).length;

for (const name of Object.keys(BOARD)) console.log(`${name.padEnd(20)} 목표 ${nOk(name)}/${GOALS.length} 달성 · 용어 ${BOARD[name]["용어(%)"].toFixed(0)}%`);
const FINAL = Object.keys(BOARD).reduce((a, b) => (nOk(b) > nOk(a) || (nOk(b) === nOk(a) && BOARD[b]["용어(%)"] > BOARD[a]["용어(%)"]) ? b : a)); // 달성한 목표 수 → 용어 정확도 순
console.log("최종 시스템:", FINAL);

function bootstrapDiff(a: number[], b: number[], nBoot: number = 2000): [number, number, number] {
  const g = mulberry32(0);
  const diffs: number[] = [];
  for (let k = 0; k < nBoot; k++) {
    const idx = Array.from({ length: a.length }, () => Math.floor(g() * a.length));
    diffs.push(mean(idx.map((i) => a[i])) - mean(idx.map((i) => b[i])));
  }
  diffs.sort((x, y) => x - y);
  const q = (p: number): number => {
    const pos = ((diffs.length - 1) * p) / 100;
    const lo = Math.floor(pos);
    return diffs[lo] + (diffs[Math.min(lo + 1, diffs.length - 1)] - diffs[lo]) * (pos - lo);
  };
  return [mean(a) - mean(b), q(2.5), q(97.5)];
}

const base = Array.from({ length: 40 }, () => Math.max(0, gauss(12, 6))); // 원래 시스템 문장별 CER (도메인 문장 40개)
const ours = base.map((v) => Math.max(0, v - 8 + gauss(0, 4)));
const same = base.map((v) => Math.max(0, v + gauss(0, 4))); // 달라진 게 없는 시스템
const rows: string[] = [];
for (const [label, other] of [["우리 시스템", ours], ["변화 없는 시스템", same]] as [string, number[]][]) {
  const [d, lo, hi] = bootstrapDiff(base, other);
  const v = lo > 0 ? "개선 ✓" : hi < 0 ? "악화 ✗" : "차이 불확실";
  rows.push(v);
  console.log(`원래 − ${label}: ${d.toFixed(2).padStart(5)}%p · 95% [${lo.toFixed(2).padStart(5)}, ${hi.toFixed(2).padStart(5)}] → ${v}`);
}
check(FINAL === "⑤ LoRA + 용어 사전" && nOk("③ LoRA") === 2 && nOk("④ LoRA + 프롬프트") === 2 && rows.join() === "개선 ✓,차이 불확실",
  "목표를 가장 많이 달성한 ⑤가 최종이고, 구간 하한이 0보다 크면 개선 ✓ 이어야 해요.");

fix.typescript:
// D15 · Part 6 · 용어 사전 후처리 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_fix.ts   (문장 몇 개 · 인터넷·GPU 불필요)
//   받아쓰기 결과에서 용어 사전과 비슷한 단어(difflib ratio와 같은 계산)를 사전 표기로 고치고, cutoff(0.65 · 0.75 · 0.85)에 따라 고쳐지는 오류와 멀쩡한 문장이 망가지는 부작용이 어떻게 달라지는지 본다
//   흉내 낸 부분: 받아쓰기 결과는 일부러 틀리게 적은 문장
const TERMS = ["서보모터", "냉각탑", "심방세동", "와파린", "인버터 과전류"];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const normalize = (s: string): string => s.toLowerCase().replace(/[^\p{L}\p{N}_\s]/gu, "").replace(/\s+/g, "");

function similarity(a: string, b: string): number {
  // 비슷한 정도 = 2 × 겹치는 글자 ÷ 전체 글자 수. 겹침은 '가장 긴 공통 조각'을 찾고 양옆을 되풀이해 센다(difflib.SequenceMatcher.ratio 와 같음)
  const matched = (alo: number, ahi: number, blo: number, bhi: number): number => {
    let bi = 0, bj = 0, bk = 0;
    for (let i = alo; i < ahi; i++) {
      for (let j = blo; j < bhi; j++) {
        let k = 0;
        while (i + k < ahi && j + k < bhi && a[i + k] === b[j + k]) k++;
        if (k > bk) { bi = i; bj = j; bk = k; }
      }
    }
    return bk === 0 ? 0 : bk + matched(alo, bi, blo, bj) + matched(bi + bk, ahi, bj + bk, bhi);
  };
  return a.length + b.length === 0 ? 1 : (2 * matched(0, a.length, 0, b.length)) / (a.length + b.length);
}

function fixTerms(text: string, terms: string[] = TERMS, cutoff: number = 0.75): string {
  const keys = terms.map((t) => [normalize(t), t] as const);
  const words = text.split(/\s+/);
  const out: string[] = [];
  let i = 0;
  while (i < words.length) {
    let best: [number, number, string, string] | null = null; // [점수, 단어 수, 용어, 뒤에 붙은 말]
    for (const n of [1, 2, 3]) { // 용어가 띄어 쓰였을 수 있으므로 1~3단어 묶음
      if (i + n > words.length) break;
      const chunk = normalize(words.slice(i, i + n).join(""));
      for (const [key, term] of keys) {
        const score = similarity(chunk.slice(0, key.length), key); // 앞부분만 비교 (뒤의 조사는 그대로 붙임)
        if (score < 1 && key.length < 3) continue; // 두 글자 용어는 정확히 같을 때만
        if (score >= cutoff && (best === null || score > best[0])) best = [score, n, term, chunk.slice(key.length)];
      }
    }
    if (best) { out.push(best[2] + best[3]); i += best[1]; } else { out.push(words[i]); i += 1; }
  }
  return out.join(" ");
}

function checkPairs(cutoff: number): [number, number] {
  const errors = [["고객에게 서보모타 설명을 드렸습니다", "고객에게 서보모터 설명을 드렸습니다"], ["기록에 심방 세동이라고 적었습니다", "기록에 심방세동이라고 적었습니다"],
    ["인버터 과전유 경보가 울렸습니다", "인버터 과전류 경보가 울렸습니다"]];
  const harmless = ["서버 모니터 화면을 확인했습니다", "냉각수 온도를 봤습니다", "인버터 과열은 아닙니다"]; // 이미 맞는 문장: 고치면 안 됨
  return [errors.filter(([w, r]) => fixTerms(w, TERMS, cutoff) === r).length, harmless.filter((h) => fixTerms(h, TERMS, cutoff) !== h).length];
}

const demo = fixTerms("고객에게 서보모타 설명을 드렸습니다", ["서보모터", "냉각탑"]);
console.log(demo, "| 비슷한 정도:", similarity("서보모타", "서보모터").toFixed(2));
console.log(fixTerms("기록에 심방 세동이라고 적었습니다", ["심방세동"]));
const table = new Map([0.5, 0.65, 0.75, 0.85].map((c) => [c, checkPairs(c)] as const));
console.log("cutoff  고친 오류(3개 중)  망가진 문장(3개 중)");
for (const [c, [f, b]] of table) console.log(`${c.toFixed(2).padStart(6)}  ${String(f).padStart(14)}  ${String(b).padStart(16)}`);
const [t75, t50, t85] = [table.get(0.75)!, table.get(0.5)!, table.get(0.85)!];
check(demo === "고객에게 서보모터 설명을 드렸습니다" && Math.abs(similarity("abcd", "abce") - 0.75) < 1e-9 && t75[0] === 3 && t75[1] === 0 && t50[1] > t75[1] && t85[0] < t75[0],
  "ratio = 2 × 겹치는 글자 ÷ 전체 글자 수이고, cutoff를 낮추면 멀쩡한 문장이 망가지고 높이면 못 고쳐요.");

