function lint(md: string): string[] {
  const problems: string[] = [];
  for (const s of SECTIONS) if (!md.split("\n").some((line) => line.startsWith("## ") && line.includes(s))) problems.push(`장 없음: ${s}`);
  if (md.includes("TODO")) problems.push("TODO가 남아 있음");
  if (!md.split("## 4. 결과")[1].split("## 5.")[0].includes(BOARD["③ LoRA"].term.toFixed(1))) problems.push("결과 표의 숫자가 BOARD와 다름");
  return problems;
}

const md = build(REPORT_TEXT);
const bad = build({ ...REPORT_TEXT, problem: "TODO: 누가 어떤 상황에서 받아쓰기를 쓰는지" });
const dir = fs.mkdtempSync(path.join(os.tmpdir(), "d15rep-"));
try {
  const file = path.join(dir, "report.md");
  fs.writeFileSync(file, md, "utf-8"); // 한글이 깨지지 않게 UTF-8로 저장
  const back = fs.readFileSync(file, "utf-8"); // 읽을 때도 같은 인코딩
  const found = lint(back);
  console.log(`리포트 ${back.trimEnd().split("\n").length}줄 · 점검 결과: ${found.length ? found : "문제 없음"}`);
  console.log("TODO가 남은 초안 점검:", lint(bad));
  check(back === md && found.length === 0 && lint(bad).join() === "TODO가 남아 있음", "저장한 리포트는 UTF-8로 그대로 읽히고, 점검은 TODO가 남은 초안만 잡아야 해요.");
} finally {
  fs.rmSync(dir, { recursive: true, force: true });
}

