// D15 · Part 9 · 발표 평가표 계산기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d15_rubric.ts   (점수는 코드 안의 예시 · 인터넷 불필요)
//   3분 발표 구성 시간(합계 180초)을 확인하고, 평가 항목별 가중치(합 100)와 동료 점수(1~5)로 팀별 총점을 계산해 순위를 낸다
//   흉내 낸 부분: 동료 평가 점수는 예시
const TALK: [string, number][] = [["문제", 30], ["데이터 · 방법", 40], ["결과 · 판정", 60], ["오류 · 한계", 30], ["다음 단계", 20]]; // 순서, 시간(초)
const WEIGHTS: Record<string, number> = { "문제 정의": 15, "방법의 타당성": 20, "결과 · 판정의 정직함": 30, "한계 설명": 20, "전달력": 15 }; // 합 100
const SCORES: Record<string, Record<string, number[]>> = { // 팀별 동료 평가: 항목마다 평가자 3명의 점수(1~5)
  "1조": { "문제 정의": [5, 4, 4], "방법의 타당성": [4, 4, 5], "결과 · 판정의 정직함": [5, 5, 4], "한계 설명": [4, 3, 4], "전달력": [3, 4, 4] },
  "2조": { "문제 정의": [3, 4, 3], "방법의 타당성": [3, 3, 4], "결과 · 판정의 정직함": [2, 3, 3], "한계 설명": [2, 2, 3], "전달력": [5, 5, 4] },
};

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

function total(team: Record<string, number[]>): number {
  // 항목별 평균(1~5)을 가중치로 합쳐 100점 만점으로: Σ(가중치 × 평균 ÷ 5)
  return Object.entries(team).reduce((s, [k, v]) => s + (WEIGHTS[k] * (v.reduce((a, b) => a + b, 0) / v.length)) / 5, 0);
}

const sum = (a: number[]): number => a.reduce((x, y) => x + y, 0);
const talkSec = sum(TALK.map(([, s]) => s));
console.log(`발표 구성: ${TALK.map(([n, s]) => `${n} ${s}초`).join(" · ")} = ${talkSec}초 (+ 질문 60초)`);
console.log(`평가 가중치 합 = ${sum(Object.values(WEIGHTS))}`);
const scores = Object.fromEntries(Object.entries(SCORES).map(([t, s]) => [t, total(s)]));
Object.entries(scores).sort((a, b) => b[1] - a[1]).forEach(([t, v], i) => console.log(`${i + 1}위 ${t}: ${v.toFixed(1)}점`));
const perfect = Object.fromEntries(Object.keys(WEIGHTS).map((k) => [k, [5, 5, 5]]));
check(talkSec === 180 && sum(Object.values(WEIGHTS)) === 100 && Math.abs(total(perfect) - 100) < 1e-9 && scores["1조"] > scores["2조"],
  "발표 시간 합은 180초, 가중치 합은 100, 만점이면 100점이며 점수가 높은 팀이 앞서야 해요.");
